mapper.select:
SELECT c.content_id, c.menu_id, c.title, c.slug, c.body, c.summary,
       c.published_at, c.view_count
FROM tb_content c
WHERE c.site_id = #{siteId}
  AND c.slug = #{slug}

SELECT c.content_id, c.menu_id, c.title, c.slug, c.summary,
       c.published_at, c.view_count
FROM tb_content c
WHERE c.site_id = #{siteId}

ORDER BY c.published_at DESC, c.content_id DESC
LIMIT #{limit}

mapper.update:
UPDATE tb_content
SET view_count = view_count + 1
WHERE content_id = #{contentId}
